#include <esp_now.h>
#include <WiFi.h>

const int Leds[8] = {21, 19, 18, 5, 17, 16, 4, 2};

void updateLEDs(uint8_t received_data) {
    for (int i = 0; i < 8; i++) {
        int state = bitRead(received_data, i);
        digitalWrite(Leds[i], state);
    }
}

void onRecvData(const uint8_t *mac, const uint8_t *data, int len) {
    if (len < 1) return;
    uint8_t received_data = data;
    Serial.print("[Board2] Received: 0x");
    if (received_data < 0x10) Serial.print("0");
    Serial.println(received_data, HEX);
    updateLEDs(received_data);
}

void setup() {
    Serial.begin(115200);
    for (int i = 0; i < 8; i++) {
        pinMode(Leds[i], OUTPUT);
        digitalWrite(Leds[i], LOW);
    }

    WiFi.mode(WIFI_STA);
    Serial.print("Receiver MAC: ");
    Serial.println(WiFi.macAddress());

    esp_now_init();
    esp_now_register_recv_cb(onRecvData);
    Serial.println("[Board2] Receiver ready — waiting for commands...");
}

void loop() {
    delay(100);
}
